INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc10fc16-9697-433d-8f23-00cccd201274', 'efc78d74-f3e7-40e2-94dc-d719f5a9921b', 0, 'condition and error_message');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4793c34-9912-4867-b607-44c8a472c83e', 'efc78d74-f3e7-40e2-94dc-d719f5a9921b', 1, 'condition and severity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d61c7204-c65a-43df-b045-96cdab5e33f7', 'efc78d74-f3e7-40e2-94dc-d719f5a9921b', 2, 'rule and message');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('692ce06d-2d6a-4676-aca9-1eba21ddbda5', 'efc78d74-f3e7-40e2-94dc-d719f5a9921b', 3, 'check and fail_message');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a512bd0-fafa-4bdb-997b-3e464d8765b6', '6097cd6b-0c72-4659-a1a0-786eae9000ff', 0, 'No — a variable may have at most one validation block; multiple constraints must be combined into a single condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26797be2-ba00-411f-9343-67987c1d12b2', '6097cd6b-0c72-4659-a1a0-786eae9000ff', 1, 'Yes — a variable can declare multiple validation blocks, each checked independently with its own error_message');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0893b43f-b829-46f4-9091-8accd4124542', '6097cd6b-0c72-4659-a1a0-786eae9000ff', 2, 'Yes, but only if the variable''s type is a primitive type like string or number');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cecdfe09-ddd5-41f7-b53d-d2a13849f2b2', '6097cd6b-0c72-4659-a1a0-786eae9000ff', 3, 'No — additional constraints must be enforced with a separate lifecycle precondition instead');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eba9ef47-8cc7-4a6f-9bed-81f70ab47c70', '9ce1743d-14ad-4071-8951-cab51b8beab5', 0, 'During terraform plan, after the value is known but before Terraform proceeds to build the rest of the plan');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4131ed69-341b-4cba-99fa-29e62f4b34af', '9ce1743d-14ad-4071-8951-cab51b8beab5', 1, 'Only during terraform apply, never during terraform plan');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a16aa3e-a2b1-49a2-bcca-c149c34ee9b6', '9ce1743d-14ad-4071-8951-cab51b8beab5', 2, 'Only when terraform validate is run explicitly, never during plan/apply');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('36f5b7ef-475e-4a02-b7c9-56a1a70f57f6', '9ce1743d-14ad-4071-8951-cab51b8beab5', 3, 'After every resource in the configuration has already been created');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09fe8925-3274-4cd1-b506-c8ce9ee38d2f', '2f27ddba-bac9-40fb-90ee-06a5fe3c27f2', 0, 'It can now also reference other input variables, data sources, and local values in the same module, not just the variable being declared');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('915029be-8efe-4270-bbd7-11d1289f9dbb', '2f27ddba-bac9-40fb-90ee-06a5fe3c27f2', 1, 'It can now reference resources in a completely different Terraform workspace''s remote state');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('729e90a2-7f8e-48dc-bc4e-a9c145d9e007', '2f27ddba-bac9-40fb-90ee-06a5fe3c27f2', 2, 'It can now call out to an external HTTP endpoint to validate the value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec78bd6d-4855-4d42-a6f2-022afa28789c', '2f27ddba-bac9-40fb-90ee-06a5fe3c27f2', 3, 'Nothing changed; validation conditions have always been able to reference any object in the configuration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e8a3528a-79e1-4e14-9f82-2be7bb1ac094', '82fc2a25-fd79-421f-b598-82936ea0886c', 0, 'Terraform still allows it and evaluates the cross-references correctly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2ae6199-2991-4b86-9f0b-895b9940c242', '82fc2a25-fd79-421f-b598-82936ea0886c', 1, 'Terraform reports an invalid validation block: the condition must still include a reference to the variable being validated, even when referencing other objects');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d0d81c76-cd4a-444e-833c-f8f0ca6a3aba', '82fc2a25-fd79-421f-b598-82936ea0886c', 2, 'Terraform silently ignores the condition and always treats it as true');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d5a7062-3362-4974-945d-668c06a6d618', '82fc2a25-fd79-421f-b598-82936ea0886c', 3, 'Terraform automatically infers the missing self-reference and adds it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53940039-7960-4e27-bb9b-3fcfe40dce6d', '835a66bd-9a01-48d2-a770-fc810cc0155d', 0, 'Because type constraints only check the value''s basic type (that it IS a number), not business-logic bounds on what a valid number actually is — validation adds that semantic check');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3213df44-e3e7-4bfd-b908-31ebe10536a2', '835a66bd-9a01-48d2-a770-fc810cc0155d', 1, 'Because type constraints are deprecated in favor of validation blocks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed2cb80f-5217-4de2-afd2-a97a275530ea', '835a66bd-9a01-48d2-a770-fc810cc0155d', 2, 'Because validation blocks are required for every numeric variable by the Terraform language');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('527774c9-e9f5-47eb-8a61-a346d8943056', '835a66bd-9a01-48d2-a770-fc810cc0155d', 3, 'Because type = number alone would otherwise accept string input silently');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eec1fede-4f12-4fe0-a6af-8dfe6006e0b9', 'd7344836-8532-4275-8ba3-d738f0a0bc0d', 0, 'Combine both boolean sub-expressions with && (or the alltrue() function over a list of conditions) inside one validation block''s condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d730f19f-abd8-4d93-906b-cf0a1749fa49', 'd7344836-8532-4275-8ba3-d738f0a0bc0d', 1, 'Use two separate error_message arguments in the same validation block');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66868a7c-960e-4568-9164-58724bc87e59', 'd7344836-8532-4275-8ba3-d738f0a0bc0d', 2, 'Nest a second validation block inside the first one''s condition');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('248f9d88-56a8-4841-869a-66b11cce8519', 'd7344836-8532-4275-8ba3-d738f0a0bc0d', 3, 'It cannot be done in a single condition; two validation blocks are mandatory');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3906540-820b-47ac-8c48-c7596e879392', 'f9056f48-1f4c-46d9-bdb0-5e22f25d6ed6', 0, 'Yes — the condition can use expressions like a ''for'' expression or alltrue([for x in var.foo : x.port > 0]) to check every element');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('674f2609-c78d-4a8c-93ab-45dce7b9f5cd', 'f9056f48-1f4c-46d9-bdb0-5e22f25d6ed6', 1, 'No — validation blocks only work on primitive-typed variables (string, number, bool)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ac12216-78fe-4c61-a0bf-a8b541722606', 'f9056f48-1f4c-46d9-bdb0-5e22f25d6ed6', 2, 'Yes, but only the first element of the list can be checked');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c4777d7d-0a8f-4fac-acf4-7009eb1b4b89', 'f9056f48-1f4c-46d9-bdb0-5e22f25d6ed6', 3, 'No — complex types must be validated exclusively via a separate lifecycle precondition on a resource');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1a7b2c3-f5f8-4102-8c0a-767a70b3afc6', 'eb6b10a8-4e80-43a1-8b3e-503d42f16ec6', 0, 'The human-readable message displayed to the user when the condition evaluates to false, explaining what constraint was violated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6dba0f0a-943b-4483-a4c3-b8604fdf0248', 'eb6b10a8-4e80-43a1-8b3e-503d42f16ec6', 1, 'An internal error code that Terraform logs but never displays');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ee1dc1b-ba5f-40d5-a19a-bd133f630276', 'eb6b10a8-4e80-43a1-8b3e-503d42f16ec6', 2, 'A regular expression used to further validate the value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('182cc0f8-8af7-4220-9ed2-c2f3a543c478', 'eb6b10a8-4e80-43a1-8b3e-503d42f16ec6', 3, 'A fallback default value applied when the condition fails');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63335c84-dc48-48a3-91fe-0b8bef15fbaf', 'c7a90234-cd44-4745-b3a6-98f557649ae7', 0, 'Terraform halts with an error showing the validation''s error_message, and does not proceed to build a plan');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe939930-8fa1-4b3e-9521-78a0844ff0b3', 'c7a90234-cd44-4745-b3a6-98f557649ae7', 1, 'Terraform logs a warning but proceeds with the plan using the invalid value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7de5715-29c2-4798-9cbf-af56a5790931', 'c7a90234-cd44-4745-b3a6-98f557649ae7', 2, 'Terraform silently substitutes the variable''s default value instead');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0714736-04ec-4f5f-a4c2-678cb1ab3cbb', 'c7a90234-cd44-4745-b3a6-98f557649ae7', 3, 'Terraform prompts interactively for a corrected value before continuing');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3b968fe-a6b2-4cc2-87e0-0752f6592b27', 'c579ad03-da71-4c04-a6e4-a5cef94b685c', 0, 'Yes — sensitive/ephemeral marking and validation are independent features and can be combined on the same variable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('110bee72-cd5a-4b51-8bf5-272a6c118b27', 'c579ad03-da71-4c04-a6e4-a5cef94b685c', 1, 'No — sensitive and ephemeral variables are exempt from all validation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55754636-2ca2-4d45-9dae-98de47f7a661', 'c579ad03-da71-4c04-a6e4-a5cef94b685c', 2, 'Only sensitive variables can have validation; ephemeral variables cannot');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24bf1d82-e56f-4438-a9c7-49dab2f1634f', 'c579ad03-da71-4c04-a6e4-a5cef94b685c', 3, 'Only ephemeral variables can have validation; sensitive variables cannot');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dea0f16e-f747-40fb-b30d-15d37d1b6bb5', '719a2bcd-0d76-4eb1-9339-d33693defc35', 0, 'Terraform creates the new replacement resource first, and only destroys the old one after the new one is successfully created');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4af22c2-4e63-4974-af07-2c76dde5865c', '719a2bcd-0d76-4eb1-9339-d33693defc35', 1, 'Terraform always destroys the old resource first, then creates the new one, regardless of this setting');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('88ea2ae6-c003-4cc6-bd74-abdb0a867e26', '719a2bcd-0d76-4eb1-9339-d33693defc35', 2, 'Terraform creates and destroys both resources simultaneously in parallel');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb46cb00-dbd1-4470-9294-f067f58bc166', '719a2bcd-0d76-4eb1-9339-d33693defc35', 3, 'This setting has no effect on ordering; it only affects logging verbosity');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a36ecaa-5a90-4e21-a062-4d33990f1a9e', '5321a585-bb48-4545-8fc9-ce81c084cdfb', 0, 'Terraform refuses to proceed with the plan/apply and returns an error, protecting the resource from destruction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4791a128-ca3f-4ccf-b173-58f841f77204', '5321a585-bb48-4545-8fc9-ce81c084cdfb', 1, 'Terraform destroys the resource anyway but logs a warning first');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83d6f536-9938-47c7-90ed-96bcd644b74f', '5321a585-bb48-4545-8fc9-ce81c084cdfb', 2, 'Terraform automatically comments out the destroy operation and skips only that resource, applying everything else');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d1290403-9a85-4518-ac4e-c2bfca508cfc', '5321a585-bb48-4545-8fc9-ce81c084cdfb', 3, 'prevent_destroy only blocks ''terraform destroy'' at the root, not resource removal from configuration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5b74209-b753-4774-8e23-62ad050ae706', '155bc05a-9f7e-4c81-9ff1-1b428e0a1595', 0, 'Terraform stops treating out-of-band or subsequent changes to the tags attribute as drift requiring correction in future plans, leaving whatever value is actually present');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a3caa9c-8139-4659-902d-905472a34f02', '155bc05a-9f7e-4c81-9ff1-1b428e0a1595', 1, 'Terraform prevents the tags attribute from ever being set on initial creation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21eabf0d-07e9-45cc-aa55-556c81396a4b', '155bc05a-9f7e-4c81-9ff1-1b428e0a1595', 2, 'Terraform ignores changes to every attribute on the resource, not just tags');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bbf3200b-6aac-4f4a-8837-334cf2e80746', '155bc05a-9f7e-4c81-9ff1-1b428e0a1595', 3, 'Terraform automatically reverts tags to its original value on every apply');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16dd0fe8-e71d-443a-b8db-78a28f56036e', '16f46df0-c057-45b4-9627-7e5b38111180', 0, 'It ignores changes to every attribute on the resource after creation, effectively excluding the whole resource from update-in-place diffs (only true replacement-triggering changes still act)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('691658e6-c765-4272-affd-4f725662a610', '16f46df0-c057-45b4-9627-7e5b38111180', 1, 'It''s invalid syntax; ignore_changes must always list explicit attribute names');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03038ab6-f3c2-4705-bcce-82b5544264a7', '16f46df0-c057-45b4-9627-7e5b38111180', 2, 'It ignores changes only to attributes marked sensitive');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a9f27e08-c481-4e89-a2bc-d4da17951dc7', '16f46df0-c057-45b4-9627-7e5b38111180', 3, 'It behaves identically to prevent_destroy');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e713af7e-5787-4669-8346-6447e479ae59', 'a96546e9-c2e7-4878-810d-d111a1bf52b5', 0, 'Forces the resource to be replaced whenever a referenced value (another resource''s attribute, or an entire other resource) changes, even if the resource''s own arguments haven''t changed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52b9ce87-6b26-4346-8072-9babdd176444', 'a96546e9-c2e7-4878-810d-d111a1bf52b5', 1, 'Prevents a resource from ever being replaced, regardless of configuration changes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('68cc70af-ee2a-4eb8-9071-d6cf0cb8cb31', 'a96546e9-c2e7-4878-810d-d111a1bf52b5', 2, 'Triggers a data source refresh whenever the resource is replaced');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eb705b66-d40c-4a6a-9326-380cc91828e0', 'a96546e9-c2e7-4878-810d-d111a1bf52b5', 3, 'Automatically retries a failed apply a fixed number of times');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b09bbfbd-7421-4c69-a481-411fc0105296', '8db3c418-0e7b-452c-a3a6-e7d14e3c306e', 0, 'References to attributes of other resources, or to entire other resources/instances (which then triggers replacement on any change to that resource, including creation or destruction)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4fdf42d3-d0c2-4bb9-9903-3d70fc933d04', '8db3c418-0e7b-452c-a3a6-e7d14e3c306e', 1, 'Only references to input variables, never to other resources');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5775441c-b7ad-4816-9a17-2a993fe97ff3', '8db3c418-0e7b-452c-a3a6-e7d14e3c306e', 2, 'Only references to data sources, never to managed resources');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('17d4e552-08cd-4293-9783-cef0a3fe95f2', '8db3c418-0e7b-452c-a3a6-e7d14e3c306e', 3, 'Only literal string values representing version numbers');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('97b2ba8f-2219-4dd0-acb7-9887df884a5e', 'fc3995aa-08f0-4be3-91ee-4e3a787d2c50', 0, 'depends_on');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ef2d972-5050-430a-ba8d-d970e7055200', 'fc3995aa-08f0-4be3-91ee-4e3a787d2c50', 1, 'create_before_destroy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db85a697-f857-4288-9b9c-f9562f7376f2', 'fc3995aa-08f0-4be3-91ee-4e3a787d2c50', 2, 'prevent_destroy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de0b8707-3426-4fe8-99c0-58d5f0f8058c', 'fc3995aa-08f0-4be3-91ee-4e3a787d2c50', 3, 'ignore_changes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('371462a2-dc18-481f-8c43-aba7d8788ad3', '09f5ebaa-e8e7-4de8-831b-be8716b7fc0e', 0, 'depends_on is a separate, top-level argument directly inside the resource (or module) block — it is NOT nested inside the lifecycle block');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8b0712df-3822-4188-9808-1990a54d6241', '09f5ebaa-e8e7-4de8-831b-be8716b7fc0e', 1, 'depends_on must always be nested inside the lifecycle block, alongside prevent_destroy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b03e1227-9b55-40d0-b9bf-f73b18ba20e8', '09f5ebaa-e8e7-4de8-831b-be8716b7fc0e', 2, 'depends_on and lifecycle are mutually exclusive on the same resource');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4fc4a196-14fb-4cc6-997b-72f2f36ee28a', '09f5ebaa-e8e7-4de8-831b-be8716b7fc0e', 3, 'depends_on only exists inside precondition blocks');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a1985656-be11-4bcd-a853-e6f1d843ba35', 'ab89f6db-7f01-47a0-ae31-d83a96c99c1b', 0, 'Nested inside that block''s ''lifecycle { }'' block, as their own precondition/postcondition sub-blocks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58db003d-17a5-4745-afa3-a6ccebb6461c', 'ab89f6db-7f01-47a0-ae31-d83a96c99c1b', 1, 'As standalone top-level blocks alongside resource/data/output, not nested in anything');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('867335cd-31ca-4e64-88af-24e363d4dbcf', 'ab89f6db-7f01-47a0-ae31-d83a96c99c1b', 2, 'Inside the variable block that supplies the resource''s main argument');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a3d565e-bcd1-473c-8c87-b5e2f54d0cbd', 'ab89f6db-7f01-47a0-ae31-d83a96c99c1b', 3, 'Inside a separate ''conditions.tf'' file that Terraform loads automatically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2ae5945-e60a-497b-9f5e-f0a6c203b75d', '6c9a6ee5-0481-442e-af8f-bcf0017db826', 0, 'After Terraform has generated a plan for the resource but before the resource is actually created/updated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fa199e02-b889-4e64-bb44-cd265b04bacc', '6c9a6ee5-0481-442e-af8f-bcf0017db826', 1, 'After the resource has already been created, verifying its resulting attributes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5c32b421-14f4-4af4-8bc0-f63b65361fbf', '6c9a6ee5-0481-442e-af8f-bcf0017db826', 2, 'Only during terraform destroy, never during apply');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ae18210f-c7a8-4ebc-93c6-af82266d243b', '6c9a6ee5-0481-442e-af8f-bcf0017db826', 3, 'Before Terraform even parses the resource''s configuration');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('25cb12d2-16ff-43ad-85f9-e07e1b04aaf1', 'fa210457-8f94-4691-833b-83e8f4f5785b', 0, 'After Terraform has applied the change (created/updated the resource), verifying a guarantee about the resulting state — for a data source, after it is read');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('74ec4b76-c882-4aab-91e8-eef726e58764', 'fa210457-8f94-4691-833b-83e8f4f5785b', 1, 'Before the resource''s configuration is even validated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b72124da-789d-4d78-a4bf-3631daae9299', 'fa210457-8f94-4691-833b-83e8f4f5785b', 2, 'At the same moment as the precondition, evaluated in parallel');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('24248fd7-c7cd-4d40-81eb-a4a7596bc3a3', 'fa210457-8f94-4691-833b-83e8f4f5785b', 3, 'Only when the resource is being destroyed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e5eeecae-a7c3-4170-a17a-d096f781e620', '83a29412-7261-4316-b930-64b3f64d3c5b', 0, 'A precondition can check assumptions involving resource/data source attributes only known after other parts of the configuration are evaluated, not just the raw input variable''s own value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('644c67dc-0e02-4cbb-94e7-b6d245d5f19c', '83a29412-7261-4316-b930-64b3f64d3c5b', 1, 'Preconditions are strictly more limited than variable validation and can only check literal values');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c76dc11e-6a79-4bcf-989b-d3b2616ab349', '83a29412-7261-4316-b930-64b3f64d3c5b', 2, 'Preconditions replace variable validation entirely as of Terraform 1.9 and validation blocks are deprecated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83c98226-0150-4ff7-b8ff-c3c89fdb5574', '83a29412-7261-4316-b930-64b3f64d3c5b', 3, 'There is no functional difference; they are two names for the exact same feature');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('57cf055f-e0a3-410a-9b96-5fc89def817b', '2708291b-e415-4749-8770-c658f538f16c', 0, 'The resource the postcondition is attached to, letting the condition reference that resource''s own resulting attributes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c285008d-b27f-4eaa-9add-82886953152b', '2708291b-e415-4749-8770-c658f538f16c', 1, 'The Terraform CLI''s current working directory');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3e4d51ff-d6f1-4321-960d-265db8dd5f96', '2708291b-e415-4749-8770-c658f538f16c', 2, 'The parent module calling this resource');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('834ceb57-022e-42c9-8e05-26496b0c1002', '2708291b-e415-4749-8770-c658f538f16c', 3, 'The previous resource in the configuration file, regardless of relationship');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('54f70947-62eb-42d7-ae98-1d0bca874147', '0e31f156-b4b4-4451-84db-650711855671', 0, 'A value that Terraform uses only during the current operation and never persists to state or plan files');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('81157250-6b8b-4a9e-9a9c-65c1cb415eac', '0e31f156-b4b4-4451-84db-650711855671', 1, 'Any value that is marked sensitive = true');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('240ae254-b8ac-498e-96b8-8483c47a2054', '0e31f156-b4b4-4451-84db-650711855671', 2, 'A value that only exists for resources using the ''random'' provider');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3fef3ab4-4dd2-4c4a-a16e-1227686827d5', '0e31f156-b4b4-4451-84db-650711855671', 3, 'A deprecated term for a ''local'' value that has since been renamed');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4d79d9eb-8082-4496-a86a-c29b35f43439', '351220c4-216b-4220-857f-966025982b0d', 0, 'ephemeral "<TYPE>" "<LABEL>" { ... }');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16242e4f-a1f7-4612-9cb0-e0bfd86ccd25', '351220c4-216b-4220-857f-966025982b0d', 1, 'resource "<TYPE>" "<LABEL>" { ephemeral = true ... }');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('002f59e3-8050-4d2c-a3d8-0fd0e4ea028d', '351220c4-216b-4220-857f-966025982b0d', 2, 'data "<TYPE>" "<LABEL>" { ephemeral { } }');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9493806-d825-4639-98ae-3fb4b9714277', '351220c4-216b-4220-857f-966025982b0d', 3, 'ephemeral_resource "<LABEL>" { type = "<TYPE>" }');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c86d7db-95f4-4e3d-8a9f-27d54dae56cf', '6b0f3bea-8c63-4577-b18c-597ad931d3e0', 0, 'Provider developers define which ephemeral resource types their provider exposes — they come from providers, not from Terraform core');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ed61a62-05e0-4715-b622-47fe524a2ae6', '6b0f3bea-8c63-4577-b18c-597ad931d3e0', 1, 'They are a fixed, built-in list hard-coded into Terraform core, the same for every provider');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4254a77f-b58b-4ea0-9310-4b09204c3c3c', '6b0f3bea-8c63-4577-b18c-597ad931d3e0', 2, 'They can only be defined inside a user''s own root module using a special ''ephemeral_type'' block');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aba7191f-c4bc-47e0-a250-1af73636cd64', '6b0f3bea-8c63-4577-b18c-597ad931d3e0', 3, 'Every existing managed resource type automatically also has an ephemeral equivalent');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e921e2bf-6f68-4490-a12a-c317d801adc2', '3454cd78-7854-4366-9041-1a43f57a90c3', 0, 'ephemeral.random_password.db_password.result');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac5cdbdc-7a30-4cf2-b5fe-08425226bb84', '3454cd78-7854-4366-9041-1a43f57a90c3', 1, 'random_password.db_password.result');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd63242f-7166-4c9e-9138-a2efaf2f4375', '3454cd78-7854-4366-9041-1a43f57a90c3', 2, 'data.ephemeral.random_password.db_password.result');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2eeb2da8-c8e2-45a6-aebb-07a617bd4021', '3454cd78-7854-4366-9041-1a43f57a90c3', 3, 'var.ephemeral.random_password.db_password');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aacd3347-8aed-46cb-9b43-f08119042c40', '289a31f6-3342-46cc-b8dc-8530abc148e9', 0, 'No — Terraform never stores ephemeral resource information in state or plan files, by design');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f6ae8aec-5351-4226-ac3b-d1e9dc32f4ec', '289a31f6-3342-46cc-b8dc-8530abc148e9', 1, 'Yes, but only their attribute names, never their values');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('092b1ef7-a27d-4ac1-8cf5-a6af8a03442b', '289a31f6-3342-46cc-b8dc-8530abc148e9', 2, 'Yes, they are stored in state exactly like managed resources');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0f34d60-e1db-4086-8d78-463e8841cdeb', '289a31f6-3342-46cc-b8dc-8530abc148e9', 3, 'Only if the ephemeral resource''s provider explicitly opts into state storage');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d3c4886e-2418-458a-b206-53885fdccf13', '07e9b83a-3749-4186-bec3-88af0505df44', 0, 'Open (when Terraform first needs its result), an optional periodic renew (if needed longer than the remote system''s expiration), then close (once dependent providers finish using it for that run phase)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('451cf31c-4af6-424b-a1cb-322f8d706a68', '07e9b83a-3749-4186-bec3-88af0505df44', 1, 'Create, read, update, delete — identical to a managed resource''s CRUD lifecycle');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc65fa73-3e24-4818-a3f1-905fbe198653', '07e9b83a-3749-4186-bec3-88af0505df44', 2, 'Plan, apply, destroy — identical to the root module''s own lifecycle');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec7989af-cacc-496d-9e2d-281120710ed9', '07e9b83a-3749-4186-bec3-88af0505df44', 3, 'Fetch once at terraform init and cache for the lifetime of the working directory');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('295e003e-7a8c-4c8f-bf8d-cfe917e59b8d', '85f18ce9-7f2b-4fbb-b8d2-ea2382289971', 0, 'Terraform 1.11');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('872eaf0f-15c5-4b9a-b026-b5950f034665', '85f18ce9-7f2b-4fbb-b8d2-ea2382289971', 1, 'Terraform 1.0');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fda07dfc-06c5-4cdf-ac04-605b123c1178', '85f18ce9-7f2b-4fbb-b8d2-ea2382289971', 2, 'Terraform 1.5');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6b9d7277-0eff-458c-b714-153ac6ca9dcc', '85f18ce9-7f2b-4fbb-b8d2-ea2382289971', 3, 'Terraform 1.9');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07104470-4789-41ce-9c63-8dfb89ca61e5', '1fa5099f-e4a2-4549-9192-7ef0677f13e2', 0, 'null — the prior state, planned state, and final state values for a write-only argument are always null');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('471bad5d-1928-4759-9a68-c28271deec36', '1fa5099f-e4a2-4549-9192-7ef0677f13e2', 1, 'The literal value that was supplied, same as any other argument');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d74ab0b-af78-4480-b790-49c6021184b3', '1fa5099f-e4a2-4549-9192-7ef0677f13e2', 2, 'A one-way hash of the value, for drift-detection purposes only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb5e3584-c0fc-46d0-bfe3-4d92cb40ce2d', '1fa5099f-e4a2-4549-9192-7ef0677f13e2', 3, 'The value is stored in state but encrypted with a Terraform-managed key');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86166a19-a735-47bb-89e0-1bcab6f8edcb', '4b0be3de-3464-4e46-8139-cf21278b16ed', 0, 'Because a null-vs-null comparison across plans can never itself indicate a change, so a separate trigger (e.g. bumping a version number) is needed to signal the provider that the write-only value should be re-applied');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6be0dcee-6947-4109-8b09-dd87233d3a93', '4b0be3de-3464-4e46-8139-cf21278b16ed', 1, 'Because Terraform requires every write-only argument to have a matching ''_version'' argument as a hard syntax rule enforced by core, unrelated to diffing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('92e75bbd-6ce4-40d2-be8d-87c271feb90c', '4b0be3de-3464-4e46-8139-cf21278b16ed', 2, 'Because the companion argument stores an encrypted backup of the write-only value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09c6b387-5baa-4227-8f8f-34d151657614', '4b0be3de-3464-4e46-8139-cf21278b16ed', 3, 'Because write-only arguments are otherwise limited to being set exactly once, at resource creation, with no other way to update them');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('02cc82ab-0097-40b1-97f7-536d3ce06109', '66731f9a-6c1e-4c1d-b0c5-b7e3b6f9ce42', 0, 'A write-only argument can accept either an ephemeral value or an ordinary non-ephemeral value — ephemeral-compatibility is what makes it able to accept ephemeral values, not a requirement that it always does');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4169b856-6f59-4ee9-be16-82a6ab90c8aa', '66731f9a-6c1e-4c1d-b0c5-b7e3b6f9ce42', 1, 'It must always be sourced from an ephemeral resource or ephemeral-marked variable; plain literal strings are rejected');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fefafc20-6332-468d-b96c-36a30eb8051f', '66731f9a-6c1e-4c1d-b0c5-b7e3b6f9ce42', 2, 'It can only ever be a literal hardcoded value in configuration, never a reference');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('315b345c-17aa-4509-a76a-6d5ccc913c99', '66731f9a-6c1e-4c1d-b0c5-b7e3b6f9ce42', 3, 'Write-only arguments and ephemeral values are entirely unrelated features with no overlap');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b880160d-24d5-4f5d-8e83-bc300743d3b7', '37677054-84d7-4d4b-b1fd-3c323d949778', 0, 'They cannot be used with set attributes, set nested attributes, or set nested blocks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b7b69da2-27e1-4904-bd2c-7f0200a252fa', '37677054-84d7-4d4b-b1fd-3c323d949778', 1, 'They cannot be used inside any resource that also has a lifecycle block');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ec6cea6b-3523-412c-9ac0-31cdd0bf3d5b', '37677054-84d7-4d4b-b1fd-3c323d949778', 2, 'They cannot be referenced by any other resource in the same configuration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2711caa9-4843-485f-94dc-04d93389fb9c', '37677054-84d7-4d4b-b1fd-3c323d949778', 3, 'They can only be declared on data sources, never on managed resources');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('abc2e22a-0df3-4d94-9be6-b86fc6fc2659', '6b76d353-8386-4529-b1c0-4407da6532fb', 0, 'It accepts an ephemeral value (including one nested inside an object) and returns null, effectively stripping out ephemeral-ness by discarding the value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce461b3d-204e-4d6d-8fd9-e99ac255e11f', '6b76d353-8386-4529-b1c0-4407da6532fb', 1, 'It converts an ephemeral resource into a permanently persisted resource in state');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55d8e198-7b28-4b0e-8456-95af2c3659b1', '6b76d353-8386-4529-b1c0-4407da6532fb', 2, 'It marks an otherwise-ordinary value as ephemeral going forward');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fd5bd199-8dbf-4158-9049-4850c9786fed', '6b76d353-8386-4529-b1c0-4407da6532fb', 3, 'It renews an ephemeral resource''s lease without closing it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('328331b6-34b5-4001-a5a0-d804d2d0f0ea', 'dc9300ba-d397-458b-a45b-ae75a5d7d687', 0, 'Terraform 1.10');
