INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1eb7735a-f7a5-45ad-acf0-71f65c06504c', 'c012d33d-9fa5-43cb-b290-b8449d78c269', 0, 'No — an ephemeral value cannot flow into a normal output; the output itself must be declared ephemeral (or the value nullified, e.g. via ephemeralasnull()) for that to be allowed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be02861f-e39a-4e66-8595-7ff49b0066b4', 'c012d33d-9fa5-43cb-b290-b8449d78c269', 1, 'Yes — any output can freely hold an ephemeral value with no special declaration needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f78ce0d-7c82-4812-93ca-617e45c19575', 'c012d33d-9fa5-43cb-b290-b8449d78c269', 2, 'Yes, but only outputs of type string can hold ephemeral values');
